from typing import List
from textkit.normalize_whitespace import normalize_whitespace


# Case-sensitive exact matches for abbreviations that do not end a sentence.
ABBREVIATIONS = {"Mr.", "Mrs.", "Ms.", "Dr.", "Prof.", "St."}

# Characters that can terminate a sentence.
TERMINATORS = {'.', '!', '?'}

# Closing quotes/brackets that can follow a terminator.
CLOSING = {'"', "'", ')', ']'}

# Opening quotes/brackets that can start the next word.
OPENING = {'"', "'", '(', '['}


def split_sentences(text: str) -> List[str]:
    """
    Split prose into sentences.
    """
    if not text or not text.strip():
        return []

    cleaned = normalize_whitespace(text)
    words = cleaned.split()

    if not words:
        return []

    sentences = []
    current_sentence_words = []

    for i, word in enumerate(words):
        current_sentence_words.append(word)

        if _is_sentence_end(word, words, i):
            sentences.append(" ".join(current_sentence_words))
            current_sentence_words = []

    if current_sentence_words:
        sentences.append(" ".join(current_sentence_words))

    return sentences


def _is_sentence_end(word: str, words: List[str], index: int) -> bool:
    if word in ABBREVIATIONS:
        return False

    terminator_end = _find_terminator_end(word)
    if terminator_end == -1:
        return False

    if index + 1 >= len(words):
        return False

    next_word = words[index + 1]
    if not next_word:
        return False

    first_char = next_word[0]
    return first_char.isupper() or first_char.isdigit() or first_char in OPENING


def _find_terminator_end(word: str) -> int:
    i = len(word) - 1
    while i >= 0 and word[i] in CLOSING:
        i -= 1

    if i < 0:
        return -1

    if word[i] not in TERMINATORS:
        return -1

    while i >= 0 and word[i] in TERMINATORS:
        i -= 1

    return i + 1
"}}}

